import dashboardApi from "@/services/dashboardApi";
import { mapFacet } from "@/utils/dashboardMapper";
import { FACET_KEY_BY_CHART } from "@/utils/dashboardData";

// MVP scope (pattern 1: status). Add more fields/types here as needed —
// nothing else in the tab needs to change.
export const CHILD_TYPES = ["Issue", "Task"];
export const FIELDS_BY_TYPE = {
  Issue: [{ key: "status", label: "Status", facet: FACET_KEY_BY_CHART.maturity, options: ["Open", "In Review", "Closed"] }],
  Task: [{ key: "status", label: "Status", facet: FACET_KEY_BY_CHART.maturity, options: ["Not Started", "In Work", "Complete", "Blocked"] }],
};

// Project association is indexed on every child object at this 6W path
// (confirmed on Task/Issue sample responses: dataelements.project).
const PARENT_PROJECT_FACET = "ds6w:where/ds6w:context/ds6w:project";

export function fieldsFor(type) {
  return FIELDS_BY_TYPE[type] || [];
}

// One rule = { type: "Issue"|"Task", fieldKey: "status", value: "Open" }.
// Rules within the SAME child type merge as AND (one call, refine object).
// Rules across DIFFERENT child types are always OR'd — that's what makes
// this a rollup (a project matches if ANY of its children match ANY rule).
export async function runRollup(rules) {
  const byType = {};
  rules.forEach((r) => {
    (byType[r.type] = byType[r.type] || []).push(r);
  });

  const perTypeResults = await Promise.all(
    Object.entries(byType).map(async ([type, typeRules]) => {
      const refines = typeRules
        .map((r) => {
          const field = fieldsFor(type).find((f) => f.key === r.fieldKey);
          return field ? { key: field.facet, value: r.value } : null;
        })
        .filter(Boolean);
      const json = await dashboardApi.fetchFilteredDashboardData(type, refines);
      return mapFacet(json.facets || [], PARENT_PROJECT_FACET).map((f) => f.label);
    })
  );

  const union = new Set(perTypeResults.flat());
  return Array.from(union);
}

// One batch call for every matched project name — not one call per project.
export async function hydrateProjects(names) {
  if (!names.length) return [];
  const json = await dashboardApi.fetchDashboardData("Project");
  const { mapFederatedResponse } = await import("@/utils/dashboardMapper");
  const all = mapFederatedResponse(json).results;
  const set = new Set(names.map((n) => n.toLowerCase()));
  return all.filter((r) => set.has((r.title || "").toLowerCase()));
}
