<template>
  <div class="an-wrap">
    <h2 class="pg-title">Analytics</h2>
    <div class="pg-sub">Create and manage saved analytics</div>

    <div class="an-panel">
      <div class="an-top">
        <div>
          <div class="sec-title">Saved Analytics</div>
          <div class="pg-sub">{{ filtered.length }} item{{ filtered.length === 1 ? "" : "s" }}</div>
        </div>
        <button class="btn-primary" @click="editing = null; dialog = true">+ Add</button>
      </div>

      <div class="filters-row">
        <v-text-field v-model="search" prepend-inner-icon="mdi-magnify" placeholder="Search analytics" variant="outlined" density="compact" hide-details style="max-width: 320px" />
        <v-select v-model="typeFilter" :items="typeOptions" clearable label="Filter by Type" variant="outlined" density="compact" hide-details style="max-width: 220px" />
      </div>

      <div v-if="!filtered.length" class="an-empty">No saved analytics found.</div>

      <div class="an-grid">
        <div v-for="item in filtered" :key="item.id" class="an-card">
          <div class="an-card-top">
            <div class="an-icon"><v-icon icon="mdi-cog-outline" size="20" color="#0F62FE" /></div>
            <v-menu v-if="canModify(item)">
              <template #activator="{ props }">
                <v-icon icon="mdi-dots-vertical" size="18" v-bind="props" class="menu-dots" />
              </template>
              <v-list density="compact">
                <v-list-item @click="edit(item)"><v-icon icon="mdi-pencil-outline" size="16" class="mr-2" />Edit</v-list-item>
                <v-list-item @click="duplicate(item)"><v-icon icon="mdi-content-copy" size="16" class="mr-2" />Duplicate</v-list-item>
                <v-list-item @click="remove(item)"><v-icon icon="mdi-delete-outline" size="16" class="mr-2" />Delete</v-list-item>
              </v-list>
            </v-menu>
          </div>

          <div class="an-card-name link" @click="open(item)">{{ item.name }}</div>
          <div class="an-card-type">{{ item.type }}</div>
          <div class="an-card-meta"><v-icon icon="mdi-filter-variant" size="14" /> {{ (item.queries || []).length }} Queries</div>
          <div class="an-card-date">Created {{ item.createdOn }}</div>
        </div>
      </div>
    </div>

    <AddAnalyticsDialog v-model="dialog" :edit-item="editing" @saved="onSaved" />
  </div>
</template>

<script>
import { useDashboardStore } from "@/store/dashboardStore";
import analyticsApi from "@/services/analyticsApi";
import AddAnalyticsDialog from "@/components/dashboard/AddAnalyticsDialog.vue";

export default {
  name: "AnalyticsView",
  components: { AddAnalyticsDialog },
  emits: ["open"],

  setup() {
    return { store: useDashboardStore() };
  },

  data() {
    return { dialog: false, editing: null, items: [], search: "", typeFilter: null };
  },

  computed: {
    typeOptions() {
      return this.store.getTypeOptions.map((t) => t.name);
    },
    filtered() {
      const q = this.search.trim().toLowerCase();
      return this.items.filter(
        (i) =>
          (!q || i.name.toLowerCase().includes(q)) &&
          (!this.typeFilter || i.type === this.typeFilter)
      );
    },
  },

  created() {
    this.refresh();
  },

  methods: {
    async refresh() {
      try { this.items = await analyticsApi.getAnalytics(); }
      catch (e) { this.items = []; }
    },
    canModify(item) {
      const user = this.store.getUser;
      if (!user) return false;
      const me = `${user.firstName} ${user.lastName}`.trim().toLowerCase();
      return (item.createdBy || "").trim().toLowerCase() === me;
    },
    edit(item) {
      this.editing = item;
      this.dialog = true;
    },
    async duplicate(item) {
      await analyticsApi.duplicateAnalytics(item.id);
      this.refresh();
    },
    async remove(item) {
      await analyticsApi.deleteAnalytics(item.id);
      this.refresh();
    },
    onSaved({ record, isEdit }) {
      this.editing = null;
      this.refresh();
      if (!isEdit) this.open(record);
    },
    open(item) {
      this.$emit("open", item);
    },
  },
};
</script>

