<template>
  <v-dialog v-model="show" max-width="560">
    <div class="cq-dialog">
      <div class="cq-head">
        <span>Build a query</span>
        <v-icon icon="mdi-close" size="20" @click="show = false" />
      </div>

      <div class="field-label">Filters — match ANY rule (rules OR across types)</div>
      <div v-for="(r, i) in rules" :key="i" class="cq-row">
        <span class="conn">{{ i === 0 ? "WHERE" : "OR" }}</span>
        <v-select v-model="r.type" :items="CHILD_TYPES" density="compact" variant="outlined" hide-details style="max-width: 100px" @update:model-value="r.fieldKey = fieldsFor(r.type)[0]?.key; r.value = ''" />
        <v-select v-model="r.fieldKey" :items="fieldOptions(r.type)" density="compact" variant="outlined" hide-details style="max-width: 100px" />
        <v-select v-model="r.value" :items="valueOptions(r)" density="compact" variant="outlined" hide-details />
        <v-icon icon="mdi-close" size="16" class="del" @click="rules.splice(i, 1)" />
      </div>
      <button class="btn-outline" @click="addRule">+ Add rule</button>

      <div class="field-label" style="margin-top: 16px">Query preview</div>
      <div class="preview">{{ previewText }}</div>

      <div class="cq-actions">
        <span class="link" @click="show = false">Cancel</span>
        <button class="btn-primary" :disabled="!rules.length || running" @click="apply">Apply</button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
import { CHILD_TYPES, fieldsFor, runRollup, hydrateProjects } from "@/utils/calcQuery";

export default {
  name: "CalculationDialog",
  props: { modelValue: { type: Boolean, default: false } },
  emits: ["update:modelValue", "results"],

  data() {
    return { CHILD_TYPES, rules: [{ type: "Issue", fieldKey: "status", value: "Open" }], running: false };
  },

  computed: {
    show: {
      get() { return this.modelValue; },
      set(v) { this.$emit("update:modelValue", v); },
    },
    previewText() {
      return this.rules.map((r) => `${r.type}.${r.fieldKey} = "${r.value}"`).join("  OR  ") || "*";
    },
  },

  methods: {
    fieldsFor,
    fieldOptions(type) {
      return fieldsFor(type).map((f) => ({ title: f.label, value: f.key }));
    },
    valueOptions(rule) {
      return fieldsFor(rule.type).find((f) => f.key === rule.fieldKey)?.options || [];
    },
    addRule() {
      this.rules.push({ type: "Issue", fieldKey: "status", value: "" });
    },
    async apply() {
      this.running = true;
      try {
        const names = await runRollup(this.rules.filter((r) => r.value));
        const projects = await hydrateProjects(names);
        this.$emit("results", { rules: [...this.rules], projects });
        this.show = false;
      } finally {
        this.running = false;
      }
    },
  },
};
</script>

