.cq-dialog { background: #fff; border-radius: 10px; padding: 20px; }
.cq-head { display: flex; justify-content: space-between; font-weight: 700; margin-bottom: 16px; }
.field-label { font-size: 13px; font-weight: 600; margin-bottom: 8px; }
.cq-row { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.conn { width: 46px; font-size: 12px; color: #888; flex-shrink: 0; }
.del { cursor: pointer; color: #888; }
.btn-outline { background: #f0f2f5; border: none; border-radius: 8px; padding: 8px 14px; font-size: 13px; font-weight: 600; cursor: pointer; margin-bottom: 4px; }
.preview { background: #f7f7f8; border-radius: 8px; padding: 10px; font-family: monospace; font-size: 12px; color: #555; }
.cq-actions { display: flex; justify-content: flex-end; gap: 20px; align-items: center; margin-top: 18px; }
.link { color: #666; cursor: pointer; font-size: 13px; }
.btn-primary { color: #fff; background: #0f62fe; border: none; border-radius: 8px; padding: 8px 16px; font-size: 13px; font-weight: 600; cursor: pointer; }
.btn-primary:disabled { background: #bdbdbd; cursor: not-allowed; }
</style>
