import http from "./httpClient";
import { useDashboardStore } from "@/store/dashboardStore";

const API = {
  SAVED_VIEWS: "https://bwc-153.brainwaveconsulting.co.in/api/saved-views",
};

class SavedViewsApi {
  getCurrentUser() {
    const store = useDashboardStore();
    const user = store.getUser;

    return `${user?.firstName || ""} ${user?.lastName || ""}`.trim();
  }

  getSavedViews() {
    return http.get(
      `${API.SAVED_VIEWS}?serverUrl=${encodeURIComponent(window.location.origin)}`,
      { credentials: "omit" }
    );
  }

  createSavedView(data) {
    return http.post(
      API.SAVED_VIEWS,
      { ...data, serverUrl: window.location.origin },
      { credentials: "omit" }
    );
  }

  updateSavedView(id, data) {
    return http.put(
      `${API.SAVED_VIEWS}/${id}`,
      {
        ...data,
        currentUser: this.getCurrentUser(),
      },
      {
        credentials: "omit",
      }
    );
  }

  deleteSavedView(id) {
    return http.delete(
      `${API.SAVED_VIEWS}/${id}?currentUser=${encodeURIComponent(
        this.getCurrentUser()
      )}`,
      {
        credentials: "omit",
      }
    );
  }

  duplicateSavedView(id) {
    return http.post(
      `${API.SAVED_VIEWS}/${id}/duplicate`,
      {
        currentUser: this.getCurrentUser(),
      },
      {
        credentials: "omit",
      }
    );
  }
}

export default new SavedViewsApi();