<template>
  <div class="ar-wrap">
    <div class="ar-head">
      <div>
        <h2 class="ar-title">{{ item?.name }}</h2>
        <div class="ar-sub">{{ item?.type }} — {{ conditionSummary }}</div>
      </div>
      <button class="btn-outline" @click="$emit('back')">Back to Analytics</button>
    </div>

    <div v-if="loading" class="ar-loading">
      <v-progress-circular indeterminate color="#0F62FE" size="36" />
      <div class="mt-2">Scanning projects…</div>
    </div>

    <template v-else>
      <div class="ar-count">{{ results.length }} matching project{{ results.length === 1 ? "" : "s" }}</div>
      <table class="ar-table" v-if="results.length">
        <thead>
          <tr><th>Title</th><th>Owner</th><th>State</th><th>Modified</th></tr>
        </thead>
        <tbody>
          <tr v-for="(r, i) in results" :key="i">
            <td>{{ r.title }}</td><td>{{ r.owner }}</td><td>{{ r.state }}</td><td>{{ r.date }}</td>
          </tr>
        </tbody>
      </table>
      <div v-else class="ar-empty">No projects match this analytics.</div>
    </template>
  </div>
</template>

<script>
import dashboardApi from "@/services/dashboardApi";
import detailApi from "@/services/detailApi";
import { mapFederatedResponse } from "@/utils/dashboardMapper";
import { matchesCondition } from "@/utils/projectConditions";

export default {
  name: "AnalyticsResultsView",
  props: { item: { type: Object, required: true } },
  emits: ["back"],

  data() {
    return { loading: true, results: [] };
  },

  computed: {
    conditionSummary() {
      return (this.item.queries || [])
        .map((q) => (q.condition === "Contains Task" ? `Contains Task "${q.value}"` : q.condition))
        .join(" AND ");
    },
  },

  async created() {
    this.loading = true;
    try {
      const json = await dashboardApi.fetchDashboardData(this.item.type);
      const rows = mapFederatedResponse(json).results;

      const enriched = await Promise.all(
        rows.map(async (row) => {
          try {
            const detail = await detailApi.fetchDetail(this.item.type, row.resourceid);
            const ok = (this.item.queries || []).every((q) => matchesCondition(detail, q.condition, q.value));
            return ok ? row : null;
          } catch (e) {
            return null;
          }
        })
      );

      this.results = enriched.filter(Boolean);
    } finally {
      this.loading = false;
    }
  },
};
</script>

