<template>
  <div class="db-wrap">
    <div class="topbar">
      <div class="topbar-left">
        <span class="label">{{ text.typeLabel }}</span>
        <v-menu>
          <template #activator="{ props }">
            <div class="type-pill" v-bind="props" title="Change object type">
              {{ type }}
              <!-- <v-icon icon="mdi-chevron-down" size="16" /> -->
            </div>
          </template>
          <!-- <v-list density="compact">
            <v-list-item
              v-for="t in typeOptions"
              :key="t.name"
              :title="t.name"
              @click="store.setType(t.name)"
            />
          </v-list> -->
        </v-menu>
        <FilterPopup
          ref="filterPopup"
          :dashboard-data="data"
          :object-type="type"
          @apply="onApplyFilters"
        />
      </div>
      <div class="topbar-right">
        <span class="refreshed"
          >{{ text.refreshedPrefix }} {{ lastRefreshed }}</span
        >
        <v-icon
          icon="mdi-refresh"
          size="18"
          class="icon-btn"
          title="Refresh dashboard"
          :class="{ spin: refreshing }"
          @click="refresh"
        />
        <v-icon
          icon="mdi-view-dashboard-outline"
          size="18"
          class="icon-btn"
          title="View / layout settings"
          @click="viewSettingsDialog = true"
        />
        <v-icon
          icon="mdi-restore"
          size="18"
          class="icon-btn"
          title="Reset to default"
          @click="resetDialog = true"
        />
        <button
          class="btn-primary"
          title="Add a custom attribute chart"
          @click="addChartDialog = true"
        >
          {{ text.addChart }}
        </button>
        <button
          class="btn-outline"
          title="Save this dashboard view"
          @click="saveViewDialog = true"
        >
          Save Dashboard
        </button>
      </div>
    </div>

    <SaveViewDialog
      v-model="saveViewDialog"
      :edit-view="loadedView"
      @save="handleSaveView"
    />

    <div class="chips-row" v-if="activeFilters.length">
      <span v-for="(f, i) in activeFilters" :key="f" class="chip">
        {{ f }}
        <v-icon
          icon="mdi-close"
          size="12"
          title="Remove filter"
          @click="removeFilter(i)"
        />
      </span>
      <span class="clear-all" @click="clearFilters">{{ text.clearAll }}</span>
    </div>

    <ResetConfirmDialog v-model="resetDialog" @confirm="resetToDefault" />
    <AddChartDialog v-model="addChartDialog" @add="handleAddChart" />
    <ViewSettingsDialog
      v-model="viewSettingsDialog"
      :settings="viewSettings"
      @apply="store.setViewSettings($event)"
    />

    <div class="content">
      <div class="main" :class="{ compact: viewSettings.compact }">
        <StateMessage
          v-if="loadingData && !data.total"
          icon="mdi-loading"
          :title="text.loadingTitle"
          :message="text.loadingMessage"
        />
        <StateMessage
          v-else-if="errorState"
          icon="mdi-power-plug-off-outline"
          badge-color="#FDECEA"
          icon-color="#DC3545"
          :title="text.errorTitle"
          :message="text.errorMessage"
          :action-label="text.retry"
          @action="refresh"
        />
        <StateMessage
          v-else-if="!data.total"
          icon="mdi-package-variant"
          badge-color="#F0F2F5"
          icon-color="#9E9E9E"
          :title="text.emptyTitle"
          :message="text.emptyMessage"
          :action-label="text.clearFilters"
          @action="clearFilters"
        />
        <template v-else>
          <KpiCards
            v-if="viewSettings.showKpis"
            :total="data.total"
            :kpis="data.kpis"
            :type="type"
          />
          <div
            class="panel-row"
            v-for="pair in chunkedCharts"
            :key="pair[0].id"
            :style="{ gridTemplateColumns: `repeat(${pair.length}, 1fr)` }"
          >
            <ChartPanel
              v-for="c in pair"
              :key="c.id"
              :chart="c"
              @move="moveChart(c.id, $event)"
              @remove="removeChart(c.id)"
              @drill="openDrill"
              @refresh="refreshChart(c)"
            />
          </div>
        </template>
      </div>
      <DrillDownPanel
        v-if="drill.open"
        :drill="drill"
        @close="closeDrill"
        @page="goDrillPage"
      />
    </div>
  </div>
</template>

<script>
import KpiCards from "@/components/dashboard/KpiCards.vue";
import ChartPanel from "@/components/dashboard/ChartPanel.vue";
import AddChartDialog from "@/components/dashboard/AddChartDialog.vue";
import DrillDownPanel from "@/components/dashboard/DrillDownPanel.vue";
import ResetConfirmDialog from "@/components/dashboard/ResetConfirmDialog.vue";
import FilterPopup from "@/components/dashboard/FilterPopup.vue";
import ViewSettingsDialog from "@/components/dashboard/ViewSettingsDialog.vue";
import SaveViewDialog from "@/components/dashboard/SaveViewDialog.vue";
import savedViewsApi from "@/services/savedViewsApi";
import StateMessage from "@/components/common/StateMessage.vue";
import {
  DEFAULT_CHART_ORDER,
  FACET_KEY_BY_CHART,
  ATTRIBUTE_FACET_KEY,
  DATE_ATTRIBUTES,
} from "@/utils/dashboardData";
import {
  mapFederatedResponse,
  mapFacet,
  mapDateFacet,
} from "@/utils/dashboardMapper";
import { DASHBOARD_TEXT } from "@/utils/uiText";
import dashboardApi from "../services/dashboardApi.js";
import detailApi from "../services/detailApi.js";
import { useDashboardStore } from "@/store/dashboardStore";
import { toastBus } from "@/components/common/toastBus";

export default {
  name: "DashboardView",
  components: {
    KpiCards,
    ChartPanel,
    AddChartDialog,
    DrillDownPanel,
    ResetConfirmDialog,
    FilterPopup,
    ViewSettingsDialog,
    SaveViewDialog,
    StateMessage,
  },

  props: {
    restoreView: { type: Object, default: null },
    restoreAnalytics: { type: Object, default: null },
  },

  setup() {
    return { store: useDashboardStore() };
  },

  data() {
    return {
      text: DASHBOARD_TEXT,
      activeFilters: [],
      activeFacetRefines: [],
      activeQueryClauses: [],
      resetDialog: false,
      addChartDialog: false,
      saveViewDialog: false,
      loadedView: null,
      viewSettingsDialog: false,
      refreshing: false,
      loadingData: false,
      errorState: false,
      lastRefreshed: "—",
      data: {
        total: 0,
        kpis: [],
        line: [],
        lineCategories: [],
        owners: [],
        policies: [],
        results: [],
      },
      order: [...DEFAULT_CHART_ORDER],
      customCharts: {},
      nextChartId: 1,
      drill: {
        open: false,
        loading: false,
        filterLabel: "",
        total: 0,
        items: [],
        page: 1,
        chartId: null,
        raw: null,
        nextStart: null,
      },
    };
  },

  computed: {
    type() {
      return this.store.type;
    },
    typeOptions() {
      return this.store.getTypeOptions;
    },
    viewSettings() {
      return this.store.viewSettings;
    },
    defaultCharts() {
      return {
        maturity: {
          id: "maturity",
          kind: "donut",
          title: "Maturity State",
          categories: this.data.kpis.map((k) => k.label),
          rawCategories: this.data.kpis.map((k) => k.raw),
          series: this.data.kpis.map((k) => k.value),
          pct: this.data.kpis.map((k) => k.pct),
          colors: this.data.kpis.map((k) => k.color),
        },
        created: {
          id: "created",
          kind: "line",
          title: "Created Per Month",
          categories: this.data.lineCategories,
          rawCategories: this.data.lineRaw,
          series: this.data.line,
        },
        owners: {
          id: "owners",
          kind: "bar-h",
          title: "Top 10 Owners",
          categories: this.data.owners.map((o) => o.name),
          rawCategories: this.data.owners.map((o) => o.raw),
          series: this.data.owners.map((o) => o.value),
        },
        policy: {
          id: "policy",
          kind: "donut",
          title: "Policy Distribution",
          categories: this.data.policies.map((p) => p.label),
          rawCategories: this.data.policies.map((p) => p.raw),
          series: this.data.policies.map((p) => p.value),
          pct: this.data.policies.map((p) => p.pct),
          colors: this.data.policies.map((p) => p.color),
        },
      };
    },
    allCharts() {
      const lookup = { ...this.defaultCharts, ...this.customCharts };
      return this.order.map((id) => lookup[id]).filter(Boolean);
    },
    chunkedCharts() {
      const size = Math.max(1, this.viewSettings.columns || 2);
      const pairs = [];
      for (let i = 0; i < this.allCharts.length; i += size)
        pairs.push(this.allCharts.slice(i, i + size));
      return pairs;
    },
  },

  watch: {
    type() {
      this.loadData();
    },
  },

  async mounted() {
    if (this.restoreView) this.applyRestoredView(this.restoreView);
    if (this.restoreAnalytics) this.applyRestoredAnalytics(this.restoreAnalytics);
    await this.loadData();
    if (this.restoreView)
      this.$refs.filterPopup?.restoreSelection(this.activeFacetRefines);
  },

  methods: {
    applyRestoredAnalytics(item) {
      this.store.setType(item.type);
      const refines = [];
      const clauses = [];
      (item.queries || []).forEach((q) => {
        const facetKey = ATTRIBUTE_FACET_KEY[q.attribute];
        if (!facetKey) return;
        if (q.operator === "Equals") {
          refines.push({ key: facetKey, value: q.value });
          this.activeFilters.push(`${q.attribute} = ${q.value}`);
          return;
        }
        const predicate = facetKey.split("/").pop();
        const clause =
          q.operator === "Contains" ? `[${predicate}]:*${q.value}*`
          : q.operator === "Starts With" ? `[${predicate}]:${q.value}*`
          : q.operator === "Greater Than" ? `[${predicate}]>"${q.value}"`
          : `[${predicate}]<"${q.value}"`;
        clauses.push(clause);
        this.activeFilters.push(`${q.attribute} ${q.operator} ${q.value}`);
      });
      this.activeFacetRefines = refines;
      this.activeQueryClauses = clauses;
    },
    applyRestoredView(view) {
      this.loadedView = view;
      this.store.setType(view.type);
      this.activeFilters = view.chips || [];
      this.activeFacetRefines = view.facetRefines || [];
      this.order = view.order || [...DEFAULT_CHART_ORDER];
      this.customCharts = view.customCharts || {};
    },
    async handleSaveView(form) {
      const user = this.store.getUser;
      const payload = {
        ...form,
        type: this.type,
        chips: this.activeFilters,
        facetRefines: this.activeFacetRefines,
        order: this.order,
        customCharts: this.customCharts,
        createdBy: user?.firstName + " " + user?.lastName || "Unknown",
      };
      try {
        this.loadedView = this.loadedView
          ? await savedViewsApi.updateSavedView(this.loadedView.id, payload)
          : await savedViewsApi.createSavedView(payload);
        toastBus.emit("Dashboard saved successfully.", "success");
      } catch (e) {
        toastBus.emit(e.message || "Failed to save dashboard.", "error");
      }
    },

    async loadData() {
      this.loadingData = true;
      this.errorState = false;
      try {
        const json = (this.activeFacetRefines.length || this.activeQueryClauses.length)
          ? await dashboardApi.fetchFilteredDashboardData(
              this.type,
              this.activeFacetRefines,
              this.activeQueryClauses
            )
          : await dashboardApi.fetchDashboardData(this.type);
        this.data = mapFederatedResponse(json);
        this.lastRefreshed = new Date().toLocaleString();
        this.refreshAllCustomCharts();
      } catch (e) {
        this.errorState = true;
        toastBus.emit("Failed to load dashboard data.", "error");
      } finally {
        this.loadingData = false;
      }
    },

    refresh() {
      this.refreshing = true;
      this.loadData().finally(() => {
        this.refreshing = false;
      });
    },

    refreshAllCustomCharts() {
      const updated = {};
      for (const c of Object.values(this.customCharts)) {
        updated[c.id] = this.buildChartFromFacet(
          c.id,
          c.kind,
          c.title,
          c.xAttr
        );
      }
      this.customCharts = { ...this.customCharts, ...updated };
    },

    refreshChart(c) {
      if (FACET_KEY_BY_CHART[c.id]) {
        this.loadData();
      } else {
        this.customCharts = {
          ...this.customCharts,
          [c.id]: this.buildChartFromFacet(c.id, c.kind, c.title, c.xAttr),
        };
      }
    },

    buildChartFromFacet(id, kind, title, xAttr) {
      const facetKey = ATTRIBUTE_FACET_KEY[xAttr];
      const rows = !facetKey
        ? []
        : DATE_ATTRIBUTES.includes(xAttr)
        ? mapDateFacet(this.data.facets || [], facetKey)
        : mapFacet(this.data.facets || [], facetKey);
      const categories = rows.length ? rows.map((r) => r.label) : ["No data"];
      const series = rows.length ? rows.map((r) => r.value) : [0];
      return { id, kind, title, xAttr, categories, series };
    },

    handleAddChart(form) {
      const id = "c" + Date.now() + "_" + this.nextChartId++;
      // :disabled="!form.xAttr || (!isSingleAttr && !form.yAttr)"
      // const title = form.chartType === "donut" ? form.xAttr : `${form.yAttr || "Count"} by ${form.xAttr}`;
      const title = `${form.xAttr}`;
      this.customCharts = {
        ...this.customCharts,
        [id]: this.buildChartFromFacet(id, form.chartType, title, form.xAttr),
      };
      this.order = [...this.order, id];
    },

    removeChart(id) {
      this.order = this.order.filter((o) => o !== id);
      if (this.customCharts[id]) {
        const cc = { ...this.customCharts };
        delete cc[id];
        this.customCharts = cc;
      }
    },

    moveChart(id, dir) {
      const i = this.order.indexOf(id);
      const j = i + dir;
      if (i < 0 || j < 0 || j >= this.order.length) return;
      const arr = [...this.order];
      [arr[i], arr[j]] = [arr[j], arr[i]];
      this.order = arr;
    },

    resetToDefault() {
      this.order = [...DEFAULT_CHART_ORDER];
      this.customCharts = {};
      this.activeFilters = [];
      this.activeFacetRefines = [];
      this.errorState = false;
      this.$refs.filterPopup?.reset();
      this.loadData();
    },

    onApplyFilters({ chips, facetRefines }) {
      this.activeFilters = chips;
      this.activeFacetRefines = facetRefines;
      this.loadData();
    },

    removeFilter(i) {
      this.$refs.filterPopup?.removeChip(this.activeFilters[i]);
      this.activeFacetRefines.splice(i, 1);
      this.activeFilters.splice(i, 1);
      this.loadData();
    },

    clearFilters() {
      this.activeFilters = [];
      this.activeFacetRefines = [];
      this.$refs.filterPopup?.reset();
      this.loadData();
    },

    resolveFacetKey(chartId) {
      if (FACET_KEY_BY_CHART[chartId]) return FACET_KEY_BY_CHART[chartId];
      const chart = this.allCharts.find((c) => c.id === chartId);
      const attr = chart?.xAttr || chart?.title;
      return attr ? ATTRIBUTE_FACET_KEY[attr] : null;
    },

    async runDrillQuery() {
      console.log("Running drilldown query for chart:", this.drill);
      this.drill.loading = true;
      try {
        const json = await dashboardApi.fetchFacetDrilldown(
          this.type,
          this.resolveFacetKey(this.drill.chartId),
          this.drill.raw,
          10,
          this.drill.nextStart,
          this.activeFacetRefines
        );

        const mapped = mapFederatedResponse(json);
        console.log("Drilldown query result:", this.type);
        this.drill.items = mapped.results;
        console.log(this.drill.items);
        if (detailApi.hasDetailApi(this.type)) {
          this.drill.items = await Promise.all(
            this.drill.items.map(async (row) => {
              try {
                const detail = await detailApi.fetchDetail(
                  this.type,
                  row.resourceid
                );
                const attrs = this.store.type == "Project" || this.store.type == "Program"  || this.store.type == "Document"  || this.store.type == "Task"? detail?.data?.[0]?.dataelements : this.store.type == "Engineering" ? detail?.member?.[0]: {};
                const due = attrs.dueDate ? new Date(attrs.dueDate) : null;
                const delayed =
                  due && !attrs.actualFinishDate && due < new Date()
                    ? "Yes"
                    : "No";

                // const isOpen = (s) =>
                //   s &&
                //   !["Closed", "Resolved", "Cancelled", "Complete"].includes(s);
                // const openRisks = (detail?.data?.[0]?.relateddata.risks || []).filter((r) =>
                //   isOpen(r.dataelements?.state)
                // ).length;
                // const openIssues = (detail?.data?.[0]?.relateddata.issues || []).filter((i) =>
                //   isOpen(i.dataelements?.state)
                // ).length;

                return {
                  ...row,
                  ...attrs,
                  delayed,
                  // openRisks,
                  // hasOpenRisk: openRisks > 0 ? "Yes" : "No",
                  // openIssues,
                  // hasOpenIssue: openIssues > 0 ? "Yes" : "No",
                };
              } catch (e) {
                return row;
              }
            })
          );
        }
        this.drill.total = mapped.total;
        console.log("Drilldown total:", this.drill);
        // Save cursor returned by server
        this.drill.nextStart = json?.infos?.next_start || null;
      } catch (e) {
        console.error("Drilldown query failed:", e);
        toastBus.emit("Failed to load drill-down data.", "error");
        this.drill.items = [];
        this.drill.total = 0;
      } finally {
        this.drill.loading = false;
      }
    },

    openDrill({ chartId, label, raw }) {
      this.drill = {
        open: true,
        loading: true,
        filterLabel: label,
        total: 0,
        items: [],
        page: 1,
        chartId,
        raw,
      };
      this.$nextTick(() =>
        setTimeout(() => window.dispatchEvent(new Event("resize")), 50)
      );
      if (this.resolveFacetKey(chartId)) {
        this.runDrillQuery();
      } else {
        console.warn(
          "No facet key resolved for chart:",
          chartId,
          "— skipping drilldown API call."
        );
        this.drill.loading = false;
        this.drill.items = [];
        this.drill.total = 0;
      }
    },

    goDrillPage(p) {
      if (p < 1) return;

      this.drill.page = p;

      const token = this.drill.nextStart
        ? this.drill.nextStart.split(" ")[3]
        : "";

      const offset = (p - 1) * 10;
      const pageIndex = p - 1;

      this.drill.nextStart =
        p === 1 ? null : `${offset} 0 ${pageIndex} ${token}`;

      this.runDrillQuery();
    },

    closeDrill() {
      this.drill.open = false;
      this.$nextTick(() =>
        setTimeout(() => window.dispatchEvent(new Event("resize")), 50)
      );
    },
  },
};
</script>

<style scoped>
.db-wrap {
  padding: 16px 20px;
  box-sizing: border-box;
}
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  flex-wrap: wrap;
  gap: 8px;
}
.topbar-left {
  display: flex;
  align-items: center;
  gap: 10px;
}
.label {
  font-size: 13px;
  color: #666;
}
.type-pill {
  display: flex;
  align-items: center;
  gap: 2px;
  border: 1px solid #ddd;
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 13px;
  color: #0f62fe;
  background: #fff;
  cursor: pointer;
}
.topbar-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.refreshed {
  font-size: 12px;
  color: #888;
}
.icon-btn {
  color: #666;
  cursor: pointer;
}
.spin {
  animation: spin 0.7s linear;
}
@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
.chips-row {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  white-space: nowrap;
  margin-bottom: 16px;
  padding-bottom: 2px;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: #e8f0fe;
  color: #0f62fe;
  font-size: 12px;
  padding: 4px 8px;
  border-radius: 6px;
  white-space: nowrap;
  flex-shrink: 0;
}
.chip .v-icon {
  cursor: pointer;
}
.clear-all {
  font-size: 12px;
  color: #0f62fe;
  cursor: pointer;
  text-decoration: underline;
  flex-shrink: 0;
}
.content {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  height: calc(100vh - 85px);
}
.content > .drill-panel {
  flex-shrink: 0;
  position: sticky;
  top: 0;
  height: 100%;
}
.main {
  flex: 1;
  min-width: 0;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 8px;
}
.panel-row {
  display: grid;
  gap: 16px;
  margin-bottom: 16px;
}
.main.compact .panel-row {
  gap: 8px;
  margin-bottom: 8px;
}
.btn-primary {
  color: #fff;
  background: #0f62fe;
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}
.btn-primary:hover {
  background: #0b4fd1;
  box-shadow: 0 2px 8px rgba(15, 98, 254, 0.35);
}
.btn-primary:active {
  transform: scale(0.97);
}
.btn-outline {
  color: #0f62fe;
  background: #fff;
  border: 1.5px solid #0f62fe;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}
.btn-outline:hover {
  background: rgba(15, 98, 254, 0.08);
  box-shadow: 0 2px 6px rgba(15, 98, 254, 0.15);
}
.btn-outline:active {
  transform: scale(0.97);
}

@media (max-width: 900px) {
  .content {
    flex-direction: column;
  }
  .panel-row {
    grid-template-columns: 1fr !important;
  }
}
@media (max-width: 600px) {
  .db-wrap {
    padding: 12px;
  }
  .topbar-right {
    width: 100%;
    justify-content: space-between;
  }
}
.main::-webkit-scrollbar {
  width: 8px;
}

.main::-webkit-scrollbar-thumb {
  background: #c7c7c7;
  border-radius: 4px;
}

.main::-webkit-scrollbar-thumb:hover {
  background: #999;
}
</style>