export const PROJECT_CONDITIONS = ["Has Open Issue", "Has Open Risk", "Contains Task"];

const CLOSED_STATES = ["Closed", "Resolved", "Cancelled", "Complete"];
const isOpen = (s) => s && !CLOSED_STATES.includes(s);

// detail = raw response from detailApi.fetchDetail("Project", id)
export function matchesCondition(detail, condition, value) {
  const related = detail?.data?.[0]?.relateddata || {};
  if (condition === "Has Open Issue") return (related.issues || []).some((i) => isOpen(i.dataelements?.state));
  if (condition === "Has Open Risk") return (related.risks || []).some((r) => isOpen(r.dataelements?.state));
  if (condition === "Contains Task")
    return (related.tasks || []).some((t) => (t.dataelements?.title || "").toLowerCase().includes((value || "").toLowerCase()));
  return true;
}
