<template>
  <v-dialog v-model="show" max-width="480" scrollable>
    <div class="an-dialog">
      <div class="an-head">
        <div>
          <div class="an-title">Add Analytics</div>
          <div class="an-sub">Configure analytics and add queries.</div>
        </div>
        <v-icon icon="mdi-close" size="20" @click="show = false" />
      </div>

      <div class="an-body">
        <div class="field-label">Analytics Name *</div>
        <v-text-field v-model="name" placeholder="Enter a name" variant="outlined" density="compact" hide-details class="mb-4" />

        <div class="field-label">Type *</div>
        <v-select
          v-model="type"
          :items="typeOptions.map((t) => t.name)"
          label="Select Type"
          variant="outlined"
          density="compact"
          hide-details
          class="mb-4"
        />

        <div class="q-head">
          <div>
            <div class="field-label" style="margin-bottom: 0">Queries</div>
            <div class="an-sub">Add one or more conditions.</div>
          </div>
          <button class="btn-outline" :disabled="!type" @click="addQuery">+ Add Query</button>
        </div>

        <div v-for="(q, i) in queries" :key="i" class="q-card">
          <div class="q-card-head">
            <span>Query {{ i + 1 }}</span>
            <v-icon icon="mdi-delete-outline" size="18" @click="queries.splice(i, 1)" />
          </div>

          <template v-if="type === 'Project'">
            <div class="q-row-2">
              <div>
                <div class="field-label">Condition</div>
                <v-select v-model="q.condition" :items="PROJECT_CONDITIONS" variant="outlined" density="compact" hide-details />
              </div>
              <div v-if="q.condition === 'Contains Task'">
                <div class="field-label">Task Name</div>
                <v-text-field v-model="q.value" placeholder="e.g. Homologation Review" variant="outlined" density="compact" hide-details />
              </div>
            </div>
          </template>

          <div v-else class="q-row">
            <div>
              <div class="field-label">Attribute</div>
              <v-select v-model="q.attribute" :items="attributesForType" variant="outlined" density="compact" hide-details />
            </div>
            <div>
              <div class="field-label">Operator</div>
              <v-select v-model="q.operator" :items="OPERATORS" variant="outlined" density="compact" hide-details />
            </div>
            <div>
              <div class="field-label">Value</div>
              <v-text-field v-model="q.value" variant="outlined" density="compact" hide-details />
            </div>
          </div>
        </div>
      </div>

      <div class="an-actions">
        <span class="link" @click="show = false">Cancel</span>
        <button class="btn-primary" :disabled="!canSave" @click="save">Save Analytics</button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
import { useDashboardStore } from "@/store/dashboardStore";
import analyticsApi from "@/services/analyticsApi";
import { columnsForType } from "@/utils/dashboardData";
import { PROJECT_CONDITIONS } from "@/utils/projectConditions";

const OPERATORS = ["Equals", "Contains", "Starts With", "Greater Than", "Less Than"];

export default {
  name: "AddAnalyticsDialog",
  props: {
    modelValue: { type: Boolean, default: false },
    editItem: { type: Object, default: null },
  },
  emits: ["update:modelValue", "saved"],

  setup() {
    return { store: useDashboardStore() };
  },

  data() {
    return { OPERATORS, PROJECT_CONDITIONS, name: "", type: null, queries: [] };
  },

  computed: {
    show: {
      get() { return this.modelValue; },
      set(v) { this.$emit("update:modelValue", v); },
    },
    typeOptions() {
      return this.store.getTypeOptions;
    },
    attributesForType() {
      return columnsForType(this.type).map((c) => c.label);
    },
    canSave() {
      if (!this.name.trim() || !this.type) return false;
      if (this.type === "Project") {
        return this.queries.every((q) => q.condition && (q.condition !== "Contains Task" || q.value));
      }
      return this.queries.every((q) => q.attribute && q.operator && q.value);
    },
  },

  watch: {
    modelValue(v) {
      if (!v) return;
      if (this.editItem) {
        this.name = this.editItem.name;
        this.type = this.editItem.type;
        this.queries = (this.editItem.queries || []).map((q) => ({ ...q }));
      } else {
        this.name = "";
        this.type = null;
        this.queries = [];
      }
    },
  },

  methods: {
    addQuery() {
      this.queries.push(
        this.type === "Project"
          ? { condition: "Has Open Issue", value: "" }
          : { attribute: this.attributesForType[0] || "", operator: "Equals", value: "" }
      );
    },
    async save() {
      const payload = { name: this.name.trim(), type: this.type, queries: this.queries };
      const record = this.editItem
        ? await analyticsApi.updateAnalytics(this.editItem.id, payload)
        : await analyticsApi.createAnalytics(payload);
      this.$emit("saved", { record, isEdit: !!this.editItem });
      this.show = false;
    },
  },
};
</script>

