<template>
  <v-dialog
    :model-value="modelValue"
    max-width="360"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="reset-card">
      <div class="reset-head">
        <span>{{ text.title }}</span>
        <v-icon
          icon="mdi-close"
          size="18"
          @click="$emit('update:modelValue', false)"
        />
      </div>
      <div class="reset-body">
        <v-icon icon="mdi-alert-outline" color="#F59E0B" size="22" />
        <p>{{ text.body }}</p>
      </div>
      <div class="reset-actions">
        <button class="btn-outline" @click="$emit('update:modelValue', false)">
          {{ text.cancel }}
        </button>
        <button class="btn-danger" @click="confirm">{{ text.confirm }}</button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
import { RESET_DIALOG_TEXT } from "@/utils/uiText";

export default {
  name: "ResetConfirmDialog",
  props: { modelValue: { type: Boolean, default: false } },
  emits: ["update:modelValue", "confirm"],
  data() {
    return { text: RESET_DIALOG_TEXT };
  },
  methods: {
    confirm() {
      this.$emit("confirm");
      this.$emit("update:modelValue", false);
    },
  },
};
</script>

<style scoped>
.reset-card {
  background: #fff;
  border-radius: 10px;
  padding: 20px;
}
@media (max-width: 480px) {
  .reset-card { padding: 14px; }
}
.reset-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 14px;
}
.reset-body {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 13px;
  color: #555;
}
.reset-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 18px;
}
.btn-outline {
  border: 1px solid #ddd;
  background: #fff;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  cursor: pointer;
}
.btn-danger {
  background: #dc3545;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
</style>