<template>
  <v-snackbar v-model="show" :color="color" timeout="3500" location="top">
    {{ message }}
    <template #actions>
      <v-btn variant="text" size="small" @click="show = false">Close</v-btn>
    </template>
  </v-snackbar>
</template>

<script>
import { toastBus } from "./toastBus";

export default {
  name: "AppToast",
  data() {
    return { show: false, message: "", color: "success" };
  },
  mounted() {
    toastBus.on((msg, type) => {
      this.message = msg;
      this.color = type === "error" ? "error" : "success";
      this.show = true;
    });
  },
};
</script>