import http from "./httpClient";
import { useDashboardStore } from "@/store/dashboardStore";

const API = {
  ANALYTICS: "https://bwc-153.brainwaveconsulting.co.in/api/analytics",
};

class AnalyticsApi {
  getCurrentUser() {
    const store = useDashboardStore();
    const user = store.getUser;
    return `${user?.firstName || ""} ${user?.lastName || ""}`.trim();
  }

  getAnalytics() {
    return http.get(
      `${API.ANALYTICS}?serverUrl=${encodeURIComponent(window.location.origin)}`,
      { credentials: "omit" }
    );
  }

  createAnalytics(data) {
    return http.post(
      API.ANALYTICS,
      { ...data, serverUrl: window.location.origin, createdBy: this.getCurrentUser() },
      { credentials: "omit" }
    );
  }

  updateAnalytics(id, data) {
    return http.put(
      `${API.ANALYTICS}/${id}`,
      { ...data, currentUser: this.getCurrentUser() },
      { credentials: "omit" }
    );
  }

  deleteAnalytics(id) {
    return http.delete(
      `${API.ANALYTICS}/${id}?currentUser=${encodeURIComponent(this.getCurrentUser())}`,
      { credentials: "omit" }
    );
  }

  duplicateAnalytics(id) {
    return http.post(
      `${API.ANALYTICS}/${id}/duplicate`,
      { currentUser: this.getCurrentUser() },
      { credentials: "omit" }
    );
  }
}

export default new AnalyticsApi();
